contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 burnAmount) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                ? (supplyAfter == supplyBefore)
                : (burnAmount <= ownerBalanceBefore && supplyAfter == supplyBefore - burnAmount)
        );
    }

    receive() external payable {}
}

